const seen = new Map<number, { number: number; login: string; labels: string[]; state: string }>();
let page = 1;
while (page <= 20) {
  const res: any = await tools.list_issues({ repo: "acme/web", state: "open", label: "perf", page });
  const items: any[] = Array.isArray(res) ? res : (res?.items ?? []);
  if (items.length === 0) break;
  for (const it of items) {
    const labels = (it.labels ?? []).map((l: any) => l.name);
    if (it.state === "open" && labels.includes("perf") && it.assignee?.login) {
      if (!seen.has(it.number)) {
        seen.set(it.number, { number: it.number, login: it.assignee.login, labels, state: it.state });
      }
    }
  }
  if (items.length < 50) break;
  page++;
}
return { pagesChecked: page, count: seen.size, issues: [...seen.values()] };
```

